using LXMF;

namespace NomadNet.Tests;

// Generated by executing upstream NomadNetworkApp/LXMRouter/LXMPeer/LXStamper at the
// pinned revisions and source SHA-256s in NomadNetNodeProfileVectors.json.
[Trait("Category", "Integration")]
public sealed class NomadNetNodeProfileTests
{
    [PeerControlsNativeFact]
    [Trait("TestId", "T1052")]
    public async Task NativePeerRemovalPersistsAndDoesNotInventPeersOrEditStaticConfiguration()
    {
        using var profile = new Profile();
        var peerMap = profile.PeerMap();
        peerMap["peering_timebase"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds() + 60;
        profile.WritePeer(peerMap);
        await profile.ImportAsync();
        var imported = LxmPeer.FromBytes(profile.RawPeer, _ => true);
        var hash = Convert.ToHexStringLower(imported.DestinationHash);
        var settings = await NomadNetSettings.OpenAsync(profile.Target);
        await (settings with { PropagationStaticPeers = [hash] }).SaveAsync(profile.Target);
        var rns = Path.Combine(profile.Target, "isolated-rns");
        Directory.CreateDirectory(rns);
        await File.WriteAllTextAsync(Path.Combine(rns, "config"),
            "[reticulum]\nenable_transport=no\nshare_instance=no\n[interfaces]\n");
        var refused = await RunAsync($"node-unpeer {hash}\nnode-peers\nstatus\nquit\n");
        Assert.True(refused.Contains("Propagation peer was not removed", StringComparison.Ordinal), refused);
        Assert.Contains("Unresolved propagation peers: 1.", refused);
        Assert.Single((object?[])MsgPack.UnpackApplicationValue(
            await File.ReadAllBytesAsync(Path.Combine(profile.Target, "storage", "lxmf", "peers")))!);

        peerMap["peering_timebase"] = DateTimeOffset.UtcNow.ToUnixTimeSeconds() - 1;
        await File.WriteAllBytesAsync(Path.Combine(profile.Target, "storage", "lxmf", "peers"),
            MsgPack.Pack(new object?[] { MsgPack.Pack(peerMap) }));
        var output = await RunAsync($"node-peers\nnode-peer-sync {hash}\nnode-unpeer {hash}\nnode-peers\nnode-unpeer {hash}\nstatus\nquit\n");
        Assert.Contains("Unresolved propagation peers: 1.", output);
        Assert.Contains("Select an existing propagation peer.", output);
        Assert.Contains("Propagation peer removed: " + hash, output);
        Assert.Contains("Unresolved propagation peers: 0.", output);
        Assert.Contains("Reticulum identity:", output);
        Assert.Empty((object?[])MsgPack.UnpackApplicationValue(
            await File.ReadAllBytesAsync(Path.Combine(profile.Target, "storage", "lxmf", "peers")))!);
        Assert.Equal([hash], (await NomadNetSettings.OpenAsync(profile.Target)).PropagationStaticPeers);
        var restarted = await RunAsync("node-peers\nstatus\nquit\n");
        Assert.Contains("Unresolved propagation peers: 0.", restarted);
        Assert.Contains("Reticulum identity:", restarted);
        Assert.Equal([hash], (await NomadNetSettings.OpenAsync(profile.Target)).PropagationStaticPeers);

        async Task<string> RunAsync(string commands)
        {
            var binary = Environment.GetEnvironmentVariable("DOTRETICULUM_NOMADNET_BINARY");
            Assert.True(File.Exists(binary), "Set DOTRETICULUM_NOMADNET_BINARY to the frozen native candidate.");
            var start = new System.Diagnostics.ProcessStartInfo(binary!)
            { UseShellExecute = false, RedirectStandardInput = true, RedirectStandardOutput = true, RedirectStandardError = true };
            foreach (var argument in new[] { "--config", profile.Target, "--rnsconfig", rns, "--console" })
                start.ArgumentList.Add(argument);
            using var process = System.Diagnostics.Process.Start(start)!;
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(45));
            var stdout = process.StandardOutput.ReadToEndAsync(timeout.Token);
            var stderr = process.StandardError.ReadToEndAsync(timeout.Token);
            try
            {
                await process.StandardInput.WriteAsync(commands.AsMemory(), timeout.Token);
                process.StandardInput.Close();
                await process.WaitForExitAsync(timeout.Token);
                Assert.True(process.ExitCode == 0, await stderr);
                return await stdout;
            }
            finally
            {
                if (!process.HasExited)
                {
                    process.Kill(entireProcessTree: true);
                    await process.WaitForExitAsync();
                }
            }
        }
    }

    private sealed class PeerControlsNativeFactAttribute : FactAttribute
    {
        public PeerControlsNativeFactAttribute()
        {
            if (Environment.GetEnvironmentVariable("DOTRETICULUM_NOMADNET_PEER_CONTROLS") != "1")
                Skip = "Enable DOTRETICULUM_NOMADNET_PEER_CONTROLS=1 with the frozen native NomadNet binary.";
        }
    }

    [Fact]
    public void ExecutedPrimaryFixtureRecordsOpaqueStampedNodeStorageAndPeerIndices()
    {
        using var fixture = Fixture();
        var root = fixture.RootElement;
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", root.GetProperty("commit").GetString());
        Assert.True(root.GetProperty("propagationNode").GetBoolean());
        Assert.Equal(1, root.GetProperty("messages").GetInt32());
        Assert.Equal(1, root.GetProperty("peerUnhandled").GetInt32());
        var file = root.GetProperty("storeFiles")[0];
        var record = LxmPropagationNode.InspectPersistedMessage(file.GetProperty("name").GetString()!,
            Convert.FromHexString(file.GetProperty("hex").GetString()!), 10240000, 2000000000);
        Assert.Equal(root.GetProperty("transientIdHex").GetString(), Convert.ToHexStringLower(record.TransientId));
        Assert.Equal(root.GetProperty("stampValue").GetInt32(), record.StampValue);
        Assert.False(record.Expired);
    }

    [Fact]
    public async Task ImportsNodeStoresAtomicallyAndPreservesUnresolvedProofsCountersAndIndicesAcrossRestart()
    {
        using var profile = new Profile();
        var before = profile.Snapshot();
        var report = await profile.ImportAsync();
        Assert.Equal(before, profile.Snapshot());
        Assert.Empty(report.NotImportedFiles);
        Assert.Contains(report.Warnings, warning => warning.Contains("unresolved persisted peers", StringComparison.Ordinal));
        var bytes = await File.ReadAllBytesAsync(Path.Combine(profile.Target, "identity"));
        try
        {
            using var own = Identity.FromPrivateKey(bytes);
            Assert.Equal(profile.Own.HexHash, own.HexHash);
        }
        finally { CryptographicOperations.ZeroMemory(bytes); }
        await using var interfaces = new PacketInterfaceManager([]);
        await using var transport = new TransportRouter(interfaces);
        for (var restart = 0; restart < 2; restart++)
        {
            await using var node = new LxmPropagationNode(transport, profile.Own, Path.Combine(profile.Target, "storage"));
            Assert.Equal(1, node.MessageCount);
            Assert.Empty(node.Peers);
            var peer = Assert.Single(node.UnresolvedPeers);
            Assert.Equal(23, peer.Offered);
            Assert.Equal(17, peer.Outgoing);
            Assert.Equal(1, peer.UnhandledCount);
            Assert.Equal(profile.PeerBytes, peer.ToBytes());
        }
        if (!OperatingSystem.IsWindows())
            foreach (var path in Directory.GetFiles(Path.Combine(profile.Target, "storage", "lxmf"), "*", SearchOption.AllDirectories)
                .Where(path => !path.EndsWith(".lock", StringComparison.Ordinal)))
                Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(path));
        var stats = (Dictionary<object, object?>)MsgPack.UnpackApplicationValue(
            await File.ReadAllBytesAsync(Path.Combine(profile.Target, "storage", "lxmf", "node_stats")))!;
        Assert.Equal(7, MsgPack.ToInt64(stats["client_propagation_messages_received"]!));
    }

    [Fact]
    public async Task MalformedStampsPeersStatsAndStaleOrDuplicateIndicesFailWithoutRepairOrPublishedState()
    {
        var changes = new Action<Profile>[]
        {
            p => File.WriteAllBytes(p.Stats, [0xc1]),
            p => File.WriteAllBytes(p.Stats, MsgPack.Pack(new Dictionary<object, object?>())),
            p => File.WriteAllBytes(p.Stats, Enumerable.Repeat((byte)0, 4097).ToArray()),
            p => File.WriteAllBytes(p.Peers, [0xc1]),
            p => File.WriteAllBytes(p.Peers, MsgPack.Pack(new object?[] { p.RawPeer, p.RawPeer })),
            p => { var map = p.PeerMap(); map["offered"] = -1L; p.WritePeer(map); },
            p => { var map = p.PeerMap(); map["last_sync_attempt"] = null; p.WritePeer(map); },
            p => { var map = p.PeerMap(); map["peering_key"] = new object?[] { new byte[31], 13L }; p.WritePeer(map); },
            p => { var map = p.PeerMap(); map["unhandled_ids"] = new object?[] { new byte[32] }; p.WritePeer(map); },
            p => { var map = p.PeerMap(); map["unhandled_ids"] = new object?[] { p.Transient, p.Transient }; p.WritePeer(map); },
            p => { var bytes = File.ReadAllBytes(p.Message); bytes[^1] ^= 0x7f; File.WriteAllBytes(p.Message, bytes); },
            p => File.Move(p.Message, p.Message[..^2] + "99"),
            p => File.Move(p.Message, Path.Combine(Path.GetDirectoryName(p.Message)!, new string('0', 64) + "_2000000000.0_14")),
            p => File.Copy(p.Message, p.Message.Replace("2000000000.0", "2000000001.0", StringComparison.Ordinal)),
            p => File.WriteAllBytes(p.Message, new byte[128]),
            p => File.WriteAllBytes(p.Peers, MsgPack.Pack(Enumerable.Repeat((object?)p.RawPeer, 4097).ToArray())),
        };
        foreach (var change in changes)
        {
            using var profile = new Profile();
            change(profile);
            var before = profile.Snapshot();
            await Assert.ThrowsAsync<InvalidDataException>(() => profile.ImportAsync());
            Assert.Equal(before, profile.Snapshot());
            profile.AssertNotPublished();
        }
    }

    [Fact]
    public async Task ExpiryPeerByteBoundsAndDisabledNodeExclusionsAreExplicit()
    {
        using (var expired = new Profile())
        {
            File.Move(expired.Message, expired.Message.Replace("2000000000.0", "1.0", StringComparison.Ordinal));
            await Assert.ThrowsAsync<InvalidDataException>(() => expired.ImportAsync());
            expired.AssertNotPublished();
        }
        using (var oversized = new Profile())
        {
            using (var stream = new FileStream(oversized.Peers, FileMode.Create)) stream.SetLength(8 * 1024 * 1024 + 1);
            await Assert.ThrowsAsync<InvalidDataException>(() => oversized.ImportAsync());
            oversized.AssertNotPublished();
        }
        using (var disabled = new Profile())
        {
            await File.WriteAllTextAsync(Path.Combine(disabled.Source, "config"), "[client]\nenable_client=Yes\n[node]\nenable_node=No\n");
            File.WriteAllBytes(disabled.Stats, [0xc1]);
            var report = await disabled.ImportAsync();
            Assert.Contains("storage/lxmf/node_stats", report.NotImportedFiles);
            Assert.Contains("storage/lxmf/peers", report.NotImportedFiles);
            Assert.Contains(report.Warnings, warning => warning.Contains("Propagation is disabled", StringComparison.Ordinal));
        }
        using var interrupted = new Profile();
        File.WriteAllBytes(interrupted.Message + ".out", [0xc1]);
        var result = await interrupted.ImportAsync();
        Assert.Contains("storage/lxmf/messagestore/" + Path.GetFileName(interrupted.Message) + ".out", result.NotImportedFiles);
        Assert.Contains(result.Warnings, warning => warning.Contains("Interrupted propagation", StringComparison.Ordinal));
    }

    [Fact]
    public async Task ConfiguredStorageAndTransferQuotasFailWithoutEvictionOrPartialPublication()
    {
        foreach (var policy in new[] { "message_storage_limit=0.005\n", "max_transfer_size=1\nmax_sync_size=1\n" })
        {
            using var profile = new Profile(quota: true);
            await File.AppendAllTextAsync(Path.Combine(profile.Source, "config"), policy);
            var before = profile.Snapshot();
            var error = await Assert.ThrowsAsync<InvalidDataException>(() => profile.ImportAsync());
            Assert.Contains(policy.StartsWith("message_storage", StringComparison.Ordinal) ? "storage policy" : "size",
                error.ToString(), StringComparison.OrdinalIgnoreCase);
            Assert.Equal(before, profile.Snapshot());
            profile.AssertNotPublished();
        }
    }

    [Fact]
    public async Task CancellationAndLateConversationFailureRollBackNodeStateAndRetryWithoutReplacingIdentity()
    {
        using (var cancelled = new Profile())
        {
            using var source = new CancellationTokenSource();
            using var watcher = new FileSystemWatcher(Path.GetDirectoryName(cancelled.Target)!)
            { NotifyFilter = NotifyFilters.DirectoryName };
            watcher.Created += (_, args) =>
            {
                if (Path.GetFileName(args.FullPath).StartsWith("native.profile-import-", StringComparison.Ordinal))
                    source.Cancel();
            };
            watcher.EnableRaisingEvents = true;
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() => cancelled.ImportAsync(source.Token));
            Assert.True(source.IsCancellationRequested);
            cancelled.AssertNotPublished();
            watcher.EnableRaisingEvents = false;
            _ = await cancelled.ImportAsync();
        }
        using var late = new Profile();
        var conversation = Path.Combine(late.Source, "storage", "conversations", new string('1', 32));
        Directory.CreateDirectory(conversation);
        var invalid = Path.Combine(conversation, new string('2', 64));
        await File.WriteAllBytesAsync(invalid, [0xc1]);
        await Assert.ThrowsAnyAsync<Exception>(() => late.ImportAsync());
        late.AssertNotPublished();
        File.Delete(invalid);
        _ = await late.ImportAsync();
        Assert.True(File.Exists(Path.Combine(late.Target, "storage", "lxmf", "peers")));
    }

    private static JsonDocument Fixture(bool quota = false) => JsonDocument.Parse(typeof(NomadNetNodeProfileTests).Assembly
        .GetManifestResourceStream(quota ? "NomadNet.Tests.NomadNetNodeQuotaVectors.json" :
            "NomadNet.Tests.NomadNetNodeProfileVectors.json")!);

    private sealed class Profile : IDisposable
    {
        private readonly string _root = Path.Combine(FindRepositoryRoot(), "artifacts", "tests",
            "nomad-node-profile", Guid.NewGuid().ToString("N"));
        public Identity Own { get; } = Identity.Generate();
        public string Source => Path.Combine(_root, "primary");
        public string Target => Path.Combine(_root, "native");
        public string Peers => Path.Combine(Source, "storage", "lxmf", "peers");
        public string Stats => Path.Combine(Source, "storage", "lxmf", "node_stats");
        public string Message { get; }
        public byte[] RawPeer { get; }
        public byte[] PeerBytes => LxmPeer.FromBytes(RawPeer, _ => true).ToBytes();
        public byte[] Transient { get; }

        public Profile(bool quota = false)
        {
            using var fixture = Fixture(quota);
            var root = fixture.RootElement;
            var lxmf = Path.Combine(Source, "storage", "lxmf");
            Directory.CreateDirectory(Path.Combine(lxmf, "messagestore"));
            var secret = Own.ExportPrivateKey();
            try { File.WriteAllBytes(Path.Combine(Source, "storage", "identity"), secret); }
            finally { CryptographicOperations.ZeroMemory(secret); }
            File.WriteAllBytes(Path.Combine(Source, "storage", "peersettings"),
                MsgPack.Pack(new Dictionary<object, object?> { ["display_name"] = "Synthetic node" }));
            File.WriteAllText(Path.Combine(Source, "config"),
                "[client]\nenable_client=Yes\nannounce_at_start=No\n[node]\nenable_node=Yes\ndisable_propagation=No\nannounce_at_start=No\n");
            File.WriteAllBytes(Peers, Convert.FromHexString(root.GetProperty("peersHex").GetString()!));
            File.WriteAllBytes(Stats, Convert.FromHexString(root.GetProperty("statsHex").GetString()!));
            var file = root.GetProperty("storeFiles")[0];
            Message = Path.Combine(lxmf, "messagestore", file.GetProperty("name").GetString()!);
            File.WriteAllBytes(Message, Convert.FromHexString(file.GetProperty("hex").GetString()!));
            RawPeer = (byte[])((object?[])MsgPack.UnpackApplicationValue(File.ReadAllBytes(Peers))!)[0]!;
            Transient = Convert.FromHexString(root.GetProperty("transientIdHex").GetString()!);
        }

        public Task<NomadNetProfileImportReport> ImportAsync(CancellationToken token = default) =>
            NomadNetProfileImport.ImportAsync(Source, Target, Path.Combine(_root, "isolated-rns"), token);
        public Dictionary<object, object?> PeerMap() => (Dictionary<object, object?>)MsgPack.UnpackApplicationValue(RawPeer)!;
        public void WritePeer(Dictionary<object, object?> map) => File.WriteAllBytes(Peers, MsgPack.Pack(new object?[] { MsgPack.Pack(map) }));
        public string Snapshot() => string.Join('\n', Directory.GetFiles(Source, "*", SearchOption.AllDirectories)
            .Order(StringComparer.Ordinal).Select(path => Path.GetRelativePath(Source, path) + ":" + Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))));
        public void AssertNotPublished()
        {
            Assert.False(Directory.Exists(Target));
            Assert.Empty(Directory.GetDirectories(_root, "native.profile-import-*"));
        }
        private static string FindRepositoryRoot()
        {
            for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
                if (File.Exists(Path.Combine(directory.FullName, "DotReticulum.Ecosystem.slnx")))
                    return directory.FullName;
            throw new DirectoryNotFoundException("Could not locate DotReticulum.Ecosystem.slnx from the test assembly.");
        }

        public void Dispose()
        {
            Own.Dispose();
            if (Directory.Exists(_root)) Directory.Delete(_root, true);
        }
    }
}
